import Atomics

let refs = ManagedAtomic<Int>(0)

func tryAcquire() -> Bool {
    refs.compareExchange(expected: 0, desired: 1,
                        ordering: .acquiring).exchanged   // relaxed failure is fine
}

// Swift 6 strict concurrency: a non-Sendable type cannot cross an isolation
// boundary, so the compiler rejects the data races this pattern's tradeoffs describe
@MainActor final class Store {
    private let count = ManagedAtomic<Int>(0)   // Sendable: atomics can cross actors
}
